CREATE TABLE IF NOT EXISTS workflows (id INTEGER PRIMARY KEY, keyword TEXT NOT NULL, public_reply TEXT NOT NULL, email_question TEXT NOT NULL, link TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS inbox (id INTEGER PRIMARY KEY, platform TEXT NOT NULL, account_id TEXT NOT NULL, contact_id TEXT NOT NULL, kind TEXT NOT NULL, event_id TEXT NOT NULL, text TEXT NOT NULL, received_at INTEGER NOT NULL, occurred_at INTEGER, status TEXT NOT NULL, run_id INTEGER, UNIQUE(platform, account_id, kind, event_id));
CREATE TABLE IF NOT EXISTS runs (id INTEGER PRIMARY KEY, account_id TEXT NOT NULL, contact_id TEXT NOT NULL, comment_id TEXT NOT NULL, workflow_id INTEGER REFERENCES workflows(id), keyword TEXT, state TEXT NOT NULL, reply TEXT NOT NULL, question TEXT NOT NULL, link TEXT NOT NULL, wait_ms INTEGER NOT NULL, deadline INTEGER, email TEXT, answer_at INTEGER, error_code TEXT NOT NULL DEFAULT '');
CREATE UNIQUE INDEX IF NOT EXISTS active_run ON runs(account_id, contact_id) WHERE state IN ('reply_pending', 'question_pending', 'waiting_email', 'link_pending', 'unknown');
CREATE TABLE IF NOT EXISTS actions (id INTEGER PRIMARY KEY, run_id INTEGER NOT NULL REFERENCES runs(id), step TEXT NOT NULL, status TEXT NOT NULL, external_id TEXT NOT NULL DEFAULT '', error_code TEXT NOT NULL DEFAULT '', UNIQUE(run_id, step));
CREATE TABLE IF NOT EXISTS email_decisions (event_id INTEGER PRIMARY KEY REFERENCES inbox(id), run_id INTEGER NOT NULL REFERENCES runs(id), status TEXT NOT NULL, decision TEXT NOT NULL DEFAULT '', model TEXT NOT NULL DEFAULT '', instruction_version TEXT NOT NULL DEFAULT '', confidence REAL);
